require(['jquery'], function($) {
    'use strict';

    // Matches the type select both in the full edit action and in the inline (editable property) editor.
    const typeSelectSelector = 'select[id^="AI.Models.Code.ModelsClass_"][id$="_type"]';

    // Shows only the elements that are relevant for the given model type. An empty type shows everything.
    function toggleModelTypeFields(modelType) {
        document.querySelectorAll('.llm-model-sheet [data-model-type]').forEach(function(element) {
            element.hidden = modelType !== '' && element.dataset.modelType !== modelType;
        });
    }

    function getSavedModelType() {
        const container = document.querySelector('.llm-model-sheet [data-saved-model-type]');
        return container ? container.dataset.savedModelType : '';
    }

    function setSavedModelType(modelType) {
        const container = document.querySelector('.llm-model-sheet [data-saved-model-type]');
        if (container) {
            container.dataset.savedModelType = modelType;
        }
    }

    function init() {
        const typeSelect = document.querySelector(typeSelectSelector);
        if (typeSelect && !typeSelect.dataset.modelTypeToggleInitialized) {
            typeSelect.dataset.modelTypeToggleInitialized = 'true';
            toggleModelTypeFields(typeSelect.value);
            typeSelect.addEventListener('change', function() {
                toggleModelTypeFields(typeSelect.value);
            });
            // When the type is edited in place in view mode, revert the visibility when the edit is canceled and
            // remember the new type when it is saved. Both events are triggered on the editable property editor,
            // which is the closest dd ancestor of the select. The editor element is reused between edits, so remove
            // previously attached listeners first. Note that after a save, editableProperty.js also triggers a
            // cancel on the still-visible editor; that is harmless because the saved type was already updated, so
            // the cancel handler re-applies the value that was just saved.
            $(typeSelect).closest('dd')
                .off('.modelTypeToggle')
                .on('xwiki:actions:cancel.modelTypeToggle', function() {
                    toggleModelTypeFields(getSavedModelType());
                })
                .on('xwiki:document:saved.modelTypeToggle', function() {
                    setSavedModelType(typeSelect.value);
                    toggleModelTypeFields(typeSelect.value);
                });
        }
    }

    $(document).on('xwiki:dom:updated', init);
    $(init);
});

/* Keep the spacing between properties when a dt/dd pair is wrapped in a div for the type-based toggling. */
.xform dl div dt:first-of-type {
  margin-top: floor(@font-size-base * 1.4);
}
